namespace Enterprise.Billing.Controllers;

[ApiController]
[Route("api/[controller]")]
public class BillingController : ControllerBase
{
    private readonly IPaymentService _paymentService;
    private readonly SemaphoreSlim _semaphore = new(10, 10);

    public BillingController(IPaymentService paymentService)
    {
        _paymentService = paymentService;
    }

    [HttpPost("batch")]
    public async Task<IActionResult> ProcessBillingBatch([FromBody] BillingBatchRequest request)
    {
        await _semaphore.WaitAsync();
        try
        {
            var result = await _paymentService.ExecuteBillingAsync(request);
            return Ok(result);
        }
        finally
        {
            _semaphore.Release();
        }
    }
}

