namespace Enterprise.Billing.Services;

public class PaymentService : IPaymentService
{
    private readonly IOracleLedgerRepository _oracleRepo;

    public PaymentService(IOracleLedgerRepository oracleRepo)
    {
        _oracleRepo = oracleRepo;
    }

    public async Task<BillingResult> ExecuteBillingAsync(BillingBatchRequest request)
    {
        // BUG: Sync-over-async hazard
        var customer = _oracleRepo.GetCustomerAsync(request.CustomerId).Result;
        return await _oracleRepo.ProcessInvoiceAsync(customer, request.Amount);
    }
}
